def fake_model(messages):  # speelt de rol van het LLM
    last = messages[-1]
    if "result" in last:
        return {"type": "answer", "text": f"Op voorraad: {last['result']['qty']} stuks."}
    return {"type": "tool_use", "name": "get_stock", "input": {"part": "filter-A"}}

TOOLS = {"get_stock": lambda part: {"part": part, "qty": 12}}

def run_agent(goal, max_steps=5):
    messages = [{"role": "user", "content": goal}]
    for _ in range(max_steps):
        reply = fake_model(messages)
        if reply["type"] == "answer":
            return reply["text"]
        result = TOOLS[reply["name"]](**reply["input"])
        messages.append({"role": "user", "result": result})
    return "Gestopt: stap-limiet bereikt."

print(run_agent("Hoeveel filters hebben we nog?"))

MAX_STEPS = 8

def run_agent(goal: str, *, user_id: int, request_id: str) -> str:
    messages = [{"role": "user", "content": goal}]
    for step in range(MAX_STEPS):
        resp = client.messages.create(model=settings.llm_model, max_tokens=1000,
                                      system=SYSTEM_PROMPT, tools=TOOLS, messages=messages)
        log_llm_call(request_id, user_id, resp.usage, step)  # trace en kosten
        messages.append({"role": "assistant", "content": resp.content})
        if resp.stop_reason != "tool_use":
            return text_of(resp)
        results = [execute_tool(b, user_id) for b in resp.content if b.type == "tool_use"]
        messages.append({"role": "user", "content": results})
    return "Dit lukte niet binnen het maximale aantal stappen."

def execute_tool(block, user_id: int) -> dict:
    try:
        args = TOOL_SCHEMAS[block.name].model_validate(block.input)   # Pydantic
        output = HANDLERS[block.name](**args.model_dump(), user_id=user_id)
    except Exception as exc:
        output = {"error": str(exc)}          # fout terug naar het model
    return {"type": "tool_result", "tool_use_id": block.id,
            "content": json.dumps(output)}

import json

def get_order(order_id: int):
    if order_id != 7:
        raise ValueError(f"work order {order_id} bestaat niet")
    return {"id": 7, "status": "planned"}

def run_tool(handler, args):
    try:
        output = handler(**args)
    except Exception as exc:
        output = {"error": str(exc)}
    return json.dumps(output)

print(run_tool(get_order, {"order_id": 7}))
print(run_tool(get_order, {"order_id": 99}))

def cancel_appointment(appointment_id: int, *, user_id: int, confirm: bool = False):
