WORK_ORDERS = {101: {"technician_id": 4, "status": "planned"}}

def complete_work_order(order_id: int, *, user_id: int, confirm: bool = False) -> dict:
    order = WORK_ORDERS.get(order_id)
    if order is None or order["technician_id"] != user_id:
        return {"error": "work order niet gevonden"}   # verraad niet dat hij bestaat
    if not confirm:
        return {"proposal": f"Work order {order_id} afronden?", "confirm_required": True}
    order["status"] = "completed"
    return {"ok": True, "status": order["status"]}

