def assistant(question: str) -> dict:  # nep-versie voor dit voorbeeld
    if "pomp" in question:
        return {"answer": "Houd de knop 5 s ingedrukt.", "sources": ["manual-x2.pdf"]}
    return {"answer": "Dat kan ik niet beantwoorden.", "sources": []}

passed = 0
for case in CASES:
    sources = assistant(case["q"])["sources"]
    ok = case["source"] in sources if case["source"] else sources == []
    passed += ok
    print("PASS" if ok else "FAIL", case["q"])
print(f"{passed}/{len(CASES)} geslaagd")
